97:pub trait AsyncEncodeTarget {
98:    /// Error produced while starting or completing an asynchronous encode.
99:    type Error: Send + Sync + 'static;
100:
101:    /// Borrowed protobuf byte buffer for CPU-written keys, lengths, and scalars.
102:    type BufMut<'a>: BufMut + Send
103:    where
104:        Self: 'a;
