124:    /// Future-shaped adapter around [`AsyncEncodeTarget::poll_write_payload`].
125:    fn write_payload<'a>(&'a mut self, payload: EncodePayload<'a>) -> WritePayload<'a, Self>
126:    where
127:        Self: Sized,
128:    {
129:        WritePayload::new(self, payload)
