141:/// Universal generated-message state for poll-based async encoding.
142:pub struct PollEncodeState<S: AsyncEncodeTarget> {
143:    root: PollEncodeFrame,
144:    nested: Vec<PollEncodeFrame>,
145:    depth: usize,
146:    payload: S::PayloadState,
147:}
148:
149:impl<S: AsyncEncodeTarget> Default for PollEncodeState<S> {
150:    fn default() -> Self {
151:        Self {
152:            root: PollEncodeFrame::default(),
153:            nested: Vec::new(),
154:            depth: 0,
155:            payload: S::PayloadState::default(),
156:        }
157:    }
158:}
159:
160:impl<S: AsyncEncodeTarget> PollEncodeState<S> {
161:    #[inline]
162:    fn frame(&self) -> &PollEncodeFrame {
163:        if self.depth == 0 {
164:            &self.root
165:        } else {
166:            &self.nested[self.depth - 1]
167:        }
168:    }
169:
170:    #[inline]
171:    fn frame_mut(&mut self) -> &mut PollEncodeFrame {
172:        if self.depth == 0 {
173:            &mut self.root
174:        } else {
175:            &mut self.nested[self.depth - 1]
176:        }
177:    }
178:
179:    #[inline]
180:    pub fn clear(&mut self) {
181:        *self.frame_mut() = PollEncodeFrame::default();
182:        if self.depth == 0 {
183:            self.nested.clear();
184:        }
185:    }
186:
187:    #[inline]
188:    pub fn field(&self) -> usize {
189:        self.frame().field
190:    }
191:
192:    #[inline]
193:    pub fn advance_field(&mut self) {
194:        let frame = self.frame_mut();
195:        frame.field += 1;
196:        frame.index = 0;
197:        frame.phase = 0;
198:    }
199:
200:    #[inline]
201:    pub fn index(&self) -> usize {
202:        self.frame().index
203:    }
204:
205:    #[inline]
206:    pub fn set_index(&mut self, index: usize) {
207:        self.frame_mut().index = index;
208:    }
209:
210:    #[inline]
211:    pub fn phase(&self) -> u8 {
212:        self.frame().phase
213:    }
214:
215:    #[inline]
216:    pub fn set_phase(&mut self, phase: u8) {
217:        self.frame_mut().phase = phase;
218:    }
219:
220:    #[inline]
221:    pub fn enter_nested(&mut self) {
222:        let nested_index = self.depth;
223:        if self.nested.len() == nested_index {
224:            self.nested.push(PollEncodeFrame::default());
225:        }
226:        self.depth += 1;
227:    }
228:
229:    #[inline]
230:    pub fn leave_nested_pending(&mut self) {
231:        debug_assert!(self.depth > 0);
232:        self.depth -= 1;
233:    }
234:
235:    #[inline]
236:    pub fn leave_nested_ready(&mut self) {
237:        debug_assert!(self.depth > 0);
238:        let nested_index = self.depth - 1;
239:        self.nested.truncate(nested_index);
240:        self.depth -= 1;
241:    }
242:
243:    #[inline]
244:    pub fn payload_pin_mut(&mut self) -> Pin<&mut S::PayloadState> {
245:        // SAFETY: `PollEncodeState` is driven from a pinned encode future in
246:        // the async paths that can return `Pending`. CPU paths complete
247:        // synchronously and do not rely on pinning.
248:        unsafe { Pin::new_unchecked(&mut self.payload) }
249:    }
250:}
