378:pub struct EncodeMessageAsyncRef<'a, M, T>
379:where
380:    M: Message,
381:    T: AsyncEncodeTarget,
382:{
383:    message: &'a M,
384:    target: &'a mut T,
385:    options: EncodeOptions,
386:    state: PollEncodeState<T>,
387:    prepared: bool,
388:}
389:
390:impl<'a, M, T> EncodeMessageAsyncRef<'a, M, T>
391:where
392:    M: Message,
393:    T: AsyncEncodeTarget,
394:{
395:    #[inline]
396:    fn new(message: &'a M, target: &'a mut T, options: EncodeOptions) -> Self {
397:        Self {
398:            message,
399:            target,
400:            options,
401:            state: PollEncodeState::default(),
402:            prepared: false,
403:        }
404:    }
405:}
406:
407:impl<M, T> Future for EncodeMessageAsyncRef<'_, M, T>
408:where
409:    M: Message,
410:    T: AsyncEncodeTarget + Send,
411:{
412:    type Output = Result<(), T::Error>;
413:
414:    #[inline]
415:    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
416:        // SAFETY: once this future is pinned, its poll state is accessed in
417:        // place until completion or drop.
418:        let this = unsafe { self.get_unchecked_mut() };
419:
420:        if !this.prepared {
421:            let len = this.message.encoded_len();
422:            let required = if this.options.length_delimited {
423:                len + encoded_len_varint(len as u64)
424:            } else {
425:                len
426:            };
427:            let remaining = {
428:                let buf = this.target.buf_mut();
429:                buf.remaining_mut()
430:            };
431:            if required > remaining {
432:                return Poll::Ready(Err(T::encode_error(EncodeError::new(required, remaining))));
433:            }
434:
435:            if this.options.length_delimited {
436:                let mut buf = this.target.buf_mut();
437:                encode_varint(len as u64, &mut buf);
438:            }
439:            this.prepared = true;
440:        }
441:
442:        this.message
443:            .poll_encode_raw(this.target, &mut this.state, cx)
444:    }
445:}
