512:/// Engine that owns message transfer from a prost message into a destination.
513:///
514:/// The trait is intentionally separate from [`Message`], so generated structs
515:/// and existing synchronous call sites do not grow hardware-specific methods or
516:/// required async hooks.
517:pub trait EncodeEngine: Clone + Send + Sync + 'static {
518:    /// Error produced while starting or completing an encode operation.
519:    type Error: From<EncodeError> + Send + Sync + 'static;
520:
521:    /// Owned future returned for one encode operation.
522:    type Encode<M, B>: Future<Output = Result<B, Self::Error>> + Send + 'static
523:    where
524:        M: Message + Send + 'static,
525:        B: EncodeDst + Send + 'static;
526:
527:    /// Starts encoding `message` into owned destination `dst`.
528:    fn encode<M, B>(
529:        &self,
530:        message: M,
531:        dst: B,
532:        options: EncodeOptions,
533:    ) -> Result<Self::Encode<M, B>, Self::Error>
534:    where
535:        M: Message + Send + 'static,
536:        B: EncodeDst + Send + 'static;
537:}
