543:/// Ready future returned by [`CpuEngine`].
544:#[derive(Debug)]
545:pub struct CpuEncode<B> {
546:    result: Option<Result<B, EncodeError>>,
547:}
548:
549:impl<B> CpuEncode<B> {
550:    #[inline]
551:    fn new(result: Result<B, EncodeError>) -> Self {
552:        Self {
553:            result: Some(result),
554:        }
555:    }
556:
557:    /// Consumes this ready future and returns the encoded destination.
558:    ///
559:    /// This is useful for adapters that must preserve a synchronous ready fast
560:    /// path while still routing encoding through [`EncodeEngine`].
561:    #[inline]
562:    pub fn into_result(mut self) -> Result<B, EncodeError> {
