impl<T> fmt::Debug for DsaAsyncProstEncode<T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("DsaAsyncProstEncode")
            .field("stage", &self.stage)
            .finish_non_exhaustive()
    }
