        tag: u32,
        values: &'a [String],
        sink: &'a mut S,
    ) -> impl core::future::Future<Output = Result<(), S::Error>> + Send + 'a + use<'a, S>
    where
        S: AsyncEncodeTarget + Send + 'a,
    {
        async move {
            for value in values {
                encode_async(tag, value, sink).await?;
            }
            Ok(())
        }
