//! Borrowed asynchronous transfer APIs for Protocol Buffers messages.
//!
//! The async-ref API mirrors prost's synchronous encoding shape for callers
//! that already own a destination. Targets expose normal protobuf structure
//! writes through [`BufMut`] and may suspend selected `string` / `bytes`
//! payload copies.

use alloc::vec::Vec;
use bytes::BufMut;
use core::future::Future;
use core::pin::Pin;
use core::task::{Context, Poll};

use crate::encoding::varint::{encode_varint, encoded_len_varint};
use crate::{EncodeError, Message};

/// Options that control how a message is encoded by borrowed async encoders.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub struct EncodeOptions {
