    #[inline]
    fn poll_write_payload(
        &mut self,
        payload: &[u8],
        _state: Pin<&mut Self::PayloadState>,
        _cx: &mut Context<'_>,
    ) -> Poll<Result<(), Self::Error>> {
        self.buf.put_slice(payload);
        Poll::Ready(Ok(()))
    }
}

