1://! Borrowed asynchronous transfer APIs for Protocol Buffers messages.
2://!
3://! The async-ref API mirrors prost's synchronous encoding shape for callers
4://! that already own a destination. Targets expose normal protobuf structure
5://! writes through [`BufMut`] and may suspend selected `string` / `bytes`
6://! payload copies.
7:
8:use alloc::vec::Vec;
9:use bytes::BufMut;
10:use core::future::Future;
11:use core::pin::Pin;
12:use core::task::{Context, Poll};
13:
14:use crate::encoding::varint::{encode_varint, encoded_len_varint};
15:use crate::{EncodeError, Message};
16:
17:/// Options that control how a message is encoded by borrowed async encoders.
18:#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
19:pub struct EncodeOptions {
20:    /// Encode the message with a protobuf length delimiter.
21:    pub length_delimited: bool,
22:}
23:
24:/// Borrowed destination used by generated asynchronous Prost encoding.
25:///
26:/// A target exposes a short-lived [`BufMut`] view for protobuf structure writes
27:/// and a separate payload-copy hook for `string` / `bytes` field contents. The
28:/// default CPU target copies payloads immediately; experimental targets can
29:/// return [`Poll::Pending`] while an external copy engine initializes the
30:/// destination bytes.
31:pub trait AsyncEncodeTarget {
32:    /// Error produced while starting or completing an asynchronous encode.
33:    type Error: Send + Sync + 'static;
34:
35:    /// Borrowed protobuf byte buffer for CPU-written keys, lengths, and scalars.
36:    type BufMut<'a>: BufMut + Send
37:    where
38:        Self: 'a;
39:
40:    /// Per-payload state kept by poll-based generated encoders while a target
41:    /// copy is pending.
42:    type PayloadState: Default + Send;
43:
44:    /// Converts a Prost capacity error into this target's error type.
45:    fn encode_error(error: EncodeError) -> Self::Error;
46:
47:    /// Returns the byte buffer used for CPU-written protobuf structure.
48:    fn buf_mut(&mut self) -> Self::BufMut<'_>;
49:
50:    /// Copies a `string` or `bytes` payload into the destination.
51:    fn poll_write_payload(
52:        &mut self,
53:        payload: &[u8],
54:        state: Pin<&mut Self::PayloadState>,
55:        cx: &mut Context<'_>,
