use prost::{EncodeError, Message};
use std::{
    future::{Future, Ready, ready},
    marker::PhantomData,
    pin::Pin,
    task::{Context, Poll},
};
use tonic::Status;
use tonic::codec::{BufferSettings, Codec, DecodeBuf, Decoder, EncodeBuffer, Encoder};

/// A [`Codec`] that implements `application/grpc+proto` with a future-shaped Prost encoder.
#[derive(Debug, Clone)]
pub struct ProstCodec<T, U> {
    _pd: PhantomData<(T, U)>,
}

impl<T, U> ProstCodec<T, U> {
    /// Configure a ProstCodec with encoder/decoder buffer settings.
    pub fn new() -> Self {
        Self { _pd: PhantomData }
    }
}

impl<T, U> Default for ProstCodec<T, U> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T, U> ProstCodec<T, U>
where
    T: Message + Send + 'static,
    U: Message + Default + Send + 'static,
{
    /// A tool for building custom codecs based on prost encoding and decoding.
    pub fn raw_encoder(buffer_settings: BufferSettings) -> <Self as Codec>::Encoder {
        ProstEncoder {
            _pd: PhantomData,
            buffer_settings,
        }
    }

    /// A tool for building custom codecs based on prost encoding and decoding.
    pub fn raw_decoder(buffer_settings: BufferSettings) -> <Self as Codec>::Decoder {
        ProstDecoder {
            _pd: PhantomData,
            buffer_settings,
        }
    }
}

impl<T, U> Codec for ProstCodec<T, U>
where
    T: Message + Send + 'static,
    U: Message + Default + Send + 'static,
{
    type Encode = T;
    type Decode = U;

    type Encoder = ProstEncoder<T>;
    type Decoder = ProstDecoder<U>;

    fn encoder(&mut self) -> Self::Encoder {
        ProstEncoder {
            _pd: PhantomData,
            buffer_settings: BufferSettings::default(),
        }
    }

    fn decoder(&mut self) -> Self::Decoder {
        ProstDecoder {
            _pd: PhantomData,
            buffer_settings: BufferSettings::default(),
        }
    }
}

/// A [`Encoder`] that encodes `T` with Prost and returns the encoded buffer as a ready future.
#[derive(Debug, Clone, Default)]
pub struct ProstEncoder<T> {
    _pd: PhantomData<T>,
    buffer_settings: BufferSettings,
}

/// Owned future returned by [`ProstEncoder`] for one message encode.
#[derive(Debug)]
pub struct ProstEncode {
    result: Option<Result<EncodeBuffer, EncodeError>>,
}
impl ProstEncode {
    #[inline]
    fn new<T: Message>(item: T, mut buf: EncodeBuffer) -> Self {
        let result = {
            let mut encode_buf = buf.as_encode_buf();
            item.encode(&mut encode_buf)
        };

        Self {
            result: Some(result.map(|()| buf)),
        }
    }
}

impl Future for ProstEncode {
    type Output = Result<EncodeBuffer, Status>;

    fn poll(mut self: Pin<&mut Self>, _cx: &mut Context<'_>) -> Poll<Self::Output> {
        let result = self
            .result
            .take()
            .expect("ProstEncode polled after completion");
        Poll::Ready(match result {
            Ok(buf) => Ok(buf),
            Err(_error) => {
                panic!("Message only errors if not enough space")
            }
        })
    }
}

impl<T> ProstEncoder<T> {
    /// Get a new encoder with explicit buffer settings.
    pub fn new(buffer_settings: BufferSettings) -> Self {
        Self {
            _pd: PhantomData,
            buffer_settings,
        }
    }
}

impl<T: Message + Send + 'static> Encoder for ProstEncoder<T> {
    type Item = T;
    type Error = Status;

    type Encode = ProstEncode;
